import express from "express";

const app = express();
app.use(express.json());

const products = [
  { id: 7, name: "Desk lamp", priceCents: 4590 },
  { id: 8, name: "Cable tray", priceCents: 1990 },
];

app.get("/products", (req, res) => {
  res.json(products);
});

app.post("/products", (req, res) => {
  const { name, priceCents } = req.body ?? {};
  const product = { id: 9, name, priceCents };
  res.status(201).location(`/products/${product.id}`).json(product);
});

app.route("/products/:id")
  .get((req, res) => {
    const id = Number(req.params.id);
    const product = products.find((item) => item.id === id);
    if (!product) return res.status(404).json({ error: "product not found" });
    res.json(product);
  })
  .delete((req, res) => {
    res.sendStatus(204);
  });

app.listen(3000, () => console.log("http://localhost:3000/products"));

