import express from "express";

const app = express();
app.use(express.json({ limit: "256kb" }));
app.use(express.urlencoded({ extended: false, limit: "32kb" }));

app.post("/orders", (req, res) => {
  const { customer, quantity } = req.body ?? {};
  if (typeof customer !== "string" || !Number.isInteger(quantity)) {
    return res.status(422).json({ error: "customer and integer quantity are required" });
  }
  res.status(201).json({ id: "ord_7781", customer, quantity });
});

app.post("/webhooks/stripe", express.raw({ type: "application/json" }), (req, res) => {
  // req.body is a Buffer here, so the signature can be checked byte for byte
  const signature = req.get("stripe-signature");
  res.json({
    received: true,
    signaturePresent: Boolean(signature),
    bytes: req.body?.length ?? 0,
  });
});

app.use(express.static("public", { maxAge: "1h", etag: true }));
app.use("/assets", express.static("dist/assets", { maxAge: "30d", immutable: true }));
app.use("/downloads", express.static("storage/downloads", { dotfiles: "deny", index: false }));

app.use(
  "/media",
  express.static("media", {
    setHeaders(res, filePath) {
      if (filePath.endsWith(".mp4")) {
        res.setHeader("cache-control", "public, max-age=86400");
      }
    },
  }),
);

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

app.get("/orders/:orderId", (req, res, next) => {
  if (req.params.orderId !== "ord_7781") {
    return next(new HttpError(404, "order ord_7781 was not found"));
  }
  res.json({ id: "ord_7781", status: "shipped" });
});

