import assert from "node:assert/strict";
import test from "node:test";
import request from "supertest";
import { app } from "../src/app.js";

test("GET /health reports ok", async () => {
  const response = await request(app).get("/health");
  assert.equal(response.status, 200);
  assert.deepEqual(response.body, { status: "ok" });
});

test("POST /orders rejects a missing customer", async () => {
  const response = await request(app).post("/orders").send({ quantity: 2 });
  assert.equal(response.status, 422);
  assert.match(response.body.error, /customer/);
});

// Wrong: the route reads req.body before any parser has run
app.post("/orders", (req, res) => res.json(req.body));
app.use(express.json());

// Right: register the parser first
app.use(express.json());
app.post("/orders", (req, res) => res.json(req.body));

// Wrong: the second call throws ERR_HTTP_HEADERS_SENT
app.get("/orders/:orderId", (req, res) => {
  res.json({ id: req.params.orderId });
  res.status(500).json({ error: "late reply" });
});

// Right: return as soon as the response is sent
app.get("/orders/:orderId", (req, res) => {
  return res.json({ id: req.params.orderId });
});

